# Router kantor (MikroTik)
/ip dns cache print where name="toko.example.com"
/ip dns cache flush

# Laptop Linux: router kini harus memberi alamat baru, TTL 300 atau kurang
dig +noall +answer toko.example.com @192.168.1.1
#   toko.example.com.  300  IN  A  198.51.100.45

# PC admin (Windows)
ipconfig /flushdns
nslookup toko.example.com

# VPS lama, sementara sampai Sabtu 22.00: teruskan ke VPS baru (nginx)
location / {
    proxy_pass https://198.51.100.45;
    proxy_set_header Host toko.example.com;
    proxy_ssl_server_name on;
    proxy_ssl_name toko.example.com;
}
sudo nginx -t && sudo systemctl reload nginx
